```go
package main

import "fmt"

type Account struct {
    owner   string
    balance int
}

func NewAccount(owner string) *Account {
    return &Account{owner: owner}
}

func (a *Account) Deposit(amount int) { a.balance += amount }
func (a Account) Balance() int        { return a.balance }

func main() {
    account := NewAccount("Mina")
    account.Deposit(25)
    fmt.Println(account.Balance())
}
```
The constructor is an ordinary function, state is held by a struct, and methods are separate receiver declarations.

```go
package main

import "fmt"

type Logger struct{}

func (Logger) Log(message string) { fmt.Println("log:", message) }

type Service struct{ Logger }

type LogSink interface{ Log(string) }

func record(sink LogSink, message string) { sink.Log(message) }

func main() {
    service := Service{Logger: Logger{}}
    record(service, "started")
    record(service.Logger, "ready")
}
```
Both values satisfy `LogSink` through their method sets, but a `Service` value is not a `Logger` value.

```go
package main

import (
    "bytes"
    "fmt"
    "io"
)

type Report struct{ Title string }

func WriteReport(w io.Writer, report Report) error {
    _, err := fmt.Fprintln(w, report.Title)
    return err
}

func main() {
    var output bytes.Buffer
    _ = WriteReport(&output, Report{Title: "Weekly"})
    fmt.Print(output.String())
}
```
The output destination varies behind `io.Writer`; the report remains a concrete, compiler-checked data value.
